["challenge_name"=>"Masalah Teknologi Informasi","name"=>"Meninjau dan meningkatkan susunan staf Unit Teknologi Informasi dengan memilih staf berpengalaman dari unit lain, dan/atau dengan merekrut dan mempekerjakan staf baru yang berkualitas."],
["challenge_name"=>"Masalah Teknologi Informasi","name"=>"Bentuklah Unit Teknologi Informasi dengan memilih staf berpengalaman dari unit lain, dan/atau dengan merekrut dan mempekerjakan staf baru yang berkualifikasi."],
["challenge_name"=>"Masalah Teknologi Informasi","name"=>"Melatih anggota Unit TI dalam pengoperasian, pemeliharaan, dan peningkatan perangkat lunak dan peralatan untuk: 1) penganggaran dan akuntansi untuk manajemen keuangan, 2) pendapatan dari sumber sendiri, 3) perencanaan pembangunan lokal, dan 4) perencanaan dan penganggaran investasi modal."],
["challenge_name"=>"Masalah Teknologi Informasi","name"=>"Melatih anggota lain dari unit Pemerintah Daerah untuk penganggaran dan akuntansi, pendapatan dari sumber sendiri, perencanaan pembangunan lokal, serta perencanaan dan penganggaran investasi modal dalam penggunaan perangkat lunak dan peralatan."],
["challenge_name"=>"Masalah Teknologi Informasi","name"=>"Melatih staf senior dan manajer dalam penggunaan laporan keuangan, pemetaan, dan data untuk mencapai hasil yang diinginkan untuk: 1) penganggaran dan akuntansi untuk manajemen keuangan, 2) pendapatan dari sumber sendiri, 3) perencanaan pembangunan lokal, dan 4) perencanaan dan penganggaran investasi modal."],
["challenge_name"=>"Masalah Informasi","name"=>"Tinjau kebijakan, peraturan, dan standar terkini tentang transparansi keuangan dan pastikan Pemerintah Daerah mematuhi norma praktik terbaik."],
["challenge_name"=>"Masalah Informasi","name"=>"Berdasarkan kebijakan transparansi keuangan yang telah disepakati, kembangkan dan adopsi manual keterlibatan warga dengan prosedur operasional standar untuk meningkatkan transparansi dan mengurangi korupsi."],
["challenge_name"=>"Masalah Informasi","name"=>"Melaksanakan latihan pelatihan untuk meningkatkan kesadaran di kalangan pejabat Pemerintah Daerah tentang cara mencapai transparansi yang lebih besar."],
["challenge_name"=>"Masalah Informasi","name"=>"Meningkatkan cara para pemimpin masyarakat sipil, termasuk jurnalis, diberi informasi tentang proses penganggaran operasional dan modal, dan melalui keterlibatan warga mengelola umpan balik untuk memastikan transparansi publik semaksimal mungkin."],
["challenge_name"=>"Masalah Informasi","name"=>"Perkenalkan pelaporan internal bulanan mengenai: status anggaran (pendapatan, komitmen, dan pengeluaran); kinerja anggaran departemen; dan setiap perubahan aset."],
["challenge_name"=>"Masalah Informasi","name"=>"Perkenalkan penggunaan akuntansi akrual entri ganda."],
["challenge_name"=>"Masalah Informasi","name"=>"Perkenalkan peramalan dan pemantauan pendapatan & pengeluaran bulanan dengan perbandingan antara yang direncanakan dan yang aktual."],
["challenge_name"=>"Masalah Informasi","name"=>"Bentuklah fungsi audit internal yang melapor kepada Kepala Eksekutif atau badan pengelola."],
["challenge_name"=>"Masalah Informasi","name"=>"Susunlah daftar konsultan informasi manajemen (atau sumber daya alternatif) yang memiliki keahlian yang dibutuhkan."],
["challenge_name"=>"Pengawasan Lemah","name"=>"Libatkan firma akuntansi independen untuk membangun riwayat audit keuangan independen yang akan dibagikan kepada Kepala Eksekutif dan badan pengelola Pemerintah Daerah, publik, pemerintah pusat, serta calon investor dan pemberi pinjaman."],
["challenge_name"=>"Pengawasan Lemah","name"=>"Gunakan jasa firma akuntansi independen untuk melakukan audit keuangan tahunan sektor publik selama tiga hingga lima tahun sesuai praktik terbaik, dan mintalah 'surat manajemen' yang melaporkan semua masalah manajemen keuangan yang terungkap selama proses audit."],
["challenge_name"=>"Pengawasan Lemah","name"=>"Manfaatkan audit tahunan sebagai alat manajemen dengan menyampaikan hasil audit independen kepada Kepala Eksekutif dan badan pengelola untuk mendapatkan dukungan bagi perubahan yang diperlukan."],
["challenge_name"=>"Pengawasan Lemah","name"=>"Meningkatkan kualitas informasi yang tersedia bagi warga negara berdasarkan inventaris kebijakan/prosedur praktik terbaik untuk pengungkapan keuangan."],
["challenge_name"=>"Pengawasan Lemah","name"=>"Berinteraksi langsung dengan warga dan mendorong organisasi masyarakat serta jaringan advokasi untuk berpartisipasi dalam pertemuan publik Pemerintah Daerah."],
["challenge_name"=>"Pengawasan Lemah","name"=>"Pastikan bahwa sistem akuntansi Pemerintah Daerah selaras dengan sistem dan pedoman lembaga pemerintah pusat yang sesuai untuk memaksimalkan kompatibilitas dua arah."],
["challenge_name"=>"Pengawasan Lemah","name"=>"Berkoordinasi dengan pemerintah nasional terkait peraturan, standar, dan kebijakan untuk pemantauan dan pengawasan pengelolaan keuangan pemerintah daerah."],
["challenge_name"=>"Pengawasan Lemah","name"=>"Lakukan penilaian tata kelola formal terhadap setiap proyek infrastruktur besar yang direncanakan atau sedang berlangsung di kota untuk menyoroti risiko dan manfaat utama dari proyek tersebut."],
["challenge_name"=>"Pengawasan Lemah","name"=>"Mengembangkan sistem manajemen anti-penyuapan dan korupsi yang komprehensif di seluruh siklus hidup perencanaan keuangan."],
["challenge_name"=>"Masalah Personel","name"=>"Menilai produktivitas staf untuk menentukan dampak (jika ada) yang ditimbulkannya terhadap pengeluaran dan kinerja penyampaian layanan."],
["challenge_name"=>"Masalah Personel","name"=>"Tentukan penyebab tingginya tingkat pergantian karyawan dengan meminta departemen sumber daya manusia melakukan wawancara keluar (exit interview)."],
["challenge_name"=>"Masalah Personel","name"=>"Susunlah daftar konsultan Manajemen Sumber Daya Manusia (atau sumber daya alternatif) yang memiliki keahlian yang dibutuhkan."],
["challenge_name"=>"Masalah Personel","name"=>"Jika perlu, gunakan konsultan eksternal untuk menyusun dan mempertahankan program pelatihan yang komprehensif bagi seluruh staf."],
["challenge_name"=>"Masalah Personel","name"=>"Mengembangkan dan menerapkan serangkaian insentif untuk mempertahankan pekerjaan staf yang mengatasi atau mengimbangi faktor-faktor yang menyebabkan pergantian karyawan."],
["challenge_name"=>"Perencanaan Pembangunan Daerah Buruk","name"=>"Melakukan penelitian lapangan visual dengan melibatkan staf Pemerintah Daerah yang mengunjungi lokasi fisik dan menambahkan catatan pada versi cetak peta dasar Pemerintah Daerah."],
["challenge_name"=>"Perencanaan Pembangunan Daerah Buruk","name"=>"Membeli komputer dan plotter, perangkat lunak Sistem Informasi Geografis (SIG), dan perangkat lunak Sistem Penentuan Posisi Global (GPS) serta kamera yang mendukung GPS."],
["challenge_name"=>"Perencanaan Pembangunan Daerah Buruk","name"=>"Buat peta dasar digital dari citra satelit atau identifikasi properti untuk membantu memperkaya proses penyusunan rencana pengembangan fisik."],
["challenge_name"=>"Perencanaan Pembangunan Daerah Buruk","name"=>"Petakan fitur fisik seperti jalan dan drainase, air dan saluran pembuangan, lahan kosong, kawasan perumahan dan permukiman kumuh, perusahaan-perusahaan besar yang mempekerjakan banyak orang, serta area pasar formal/informal."],
["challenge_name"=>"Perencanaan Pembangunan Daerah Buruk","name"=>"Petakan fitur lingkungan seperti sungai, aliran air, dan tempat pembuangan sampah padat, serta potensi bahaya bencana."],
["challenge_name"=>"Perencanaan Pembangunan Daerah Buruk","name"=>"Petakan karakteristik sosial seperti kebutuhan dasar masyarakat dan akses terhadap layanan publik, antara lain."],
["challenge_name"=>"Perencanaan Pembangunan Daerah Buruk","name"=>"Petakan karakteristik ekonomi seperti perusahaan-perusahaan besar yang mempekerjakan banyak orang, produk-produk utama, sistem distribusi, klaster bisnis yang saling terkait dan rantai nilai, pasar keuangan, dan lain sebagainya."],
["challenge_name"=>"Perencanaan Pembangunan Daerah Buruk","name"=>"Lakukan survei global terhadap strategi-strategi yang telah berhasil diterapkan oleh Pemerintah Daerah lainnya dalam perencanaan; pilih strategi, kebijakan, dan inisiatif yang sesuai; dan implementasikan."],
["challenge_name"=>"Perencanaan Pembangunan Daerah Buruk","name"=>"Mengadakan pertemuan formal dan informal dengan para pemangku kepentingan dan pihak lain untuk membahas dan berpartisipasi dalam membentuk visi untuk masa depan wilayah tersebut."],
["challenge_name"=>"Perencanaan Pembangunan Daerah Buruk","name"=>"Menerapkan pendekatan sistematis untuk pengumpulan data gas rumah kaca dan iklim yang memberikan informasi bagi proses perencanaan pembangunan lokal, termasuk: penghitungan emisi gas rumah kaca secara menyeluruh dari Pemerintah Daerah; inventarisasi gas rumah kaca; dan analisis dampak perubahan iklim."],
["challenge_name"=>"Perencanaan Pembangunan Daerah Buruk","name"=>"Sesuaikan metodologi inventarisasi gas rumah kaca untuk memasukkan protokol dan standar global."],
["challenge_name"=>"Perencanaan Pembangunan Daerah Buruk","name"=>"Mengembangkan pendekatan komprehensif untuk ketahanan terhadap berbagai bahaya alam dan buatan manusia dengan mengubah rencana pembangunan lokal yang ada, didukung dengan penilaian ancaman dan kerentanan, strategi untuk mengatasi kerentanan dan mencapai target, kebijakan untuk memandu pembangunan, dan usulan untuk dipertimbangkan dalam rencana investasi modal saat ini dan di masa mendatang."],
["challenge_name"=>"Perencanaan Pembangunan Daerah Buruk","name"=>"Berinteraksi dengan para pemangku kepentingan untuk mengembangkan rencana investasi modal, anggaran, dan jadwal yang memprioritaskan investasi dalam proyek infrastruktur adaptasi, ketahanan, dan mitigasi iklim."],
["challenge_name"=>"Perencanaan Pembangunan Daerah Buruk","name"=>"Susun jadwal pelaksanaan proyek bergulir lima tahun dan perkiraan biaya awal untuk rencana investasi modal yang ramah iklim."],
["challenge_name"=>"Perencanaan Pembangunan Daerah Buruk","name"=>"Lakukan penilaian keberlanjutan dan ketahanan secara formal terhadap setiap proyek infrastruktur besar yang direncanakan atau sedang berlangsung di kota tersebut untuk menyoroti risiko dan manfaat utama dari proyek tersebut."],
["challenge_name"=>"Perencanaan Penanaman Modal","name"=>"Terapkan proses perencanaan investasi modal selama 15 tahun yang memungkinkan banyak pihak untuk mengevaluasi kinerja proyek modal dan kemitraan publik-swasta (PPP) yang diusulkan berdasarkan kriteria untuk memenuhi kebutuhan Pemerintah Daerah, termasuk efektivitas biaya, emisi karbon rendah, dan ketahanan."],
["challenge_name"=>"Perencanaan Penanaman Modal","name"=>"Terapkan proses perencanaan investasi modal selama 15 tahun yang mencakup evaluasi proposal proyek modal, dan menjadikan proposal, proses, serta hasilnya transparan bagi para pemangku kepentingan lokal."],
["challenge_name"=>"Perencanaan Penanaman Modal","name"=>"Gunakan rencana pembiayaan utang bergulir 5 tahun untuk proyek-proyek yang termasuk dalam Rencana Investasi Modal; perkirakan jumlah dan waktu utang baru yang dibutuhkan untuk memenuhi pengeluaran kas modal setiap tahunnya."],
["challenge_name"=>"Perencanaan Penanaman Modal","name"=>"Memberikan pengarahan kepada para pemangku kepentingan utama, termasuk jurnalis dan perwakilan masyarakat sipil lainnya, tentang rencana investasi modal dan PPP untuk memastikan transparansi publik yang maksimal dan mengelola umpan balik dari para pemangku kepentingan utama."],
["challenge_name"=>"Perencanaan Penanaman Modal","name"=>"Berdasarkan visi serta kekuatan dan kelemahan yang diidentifikasi sebagai hasil dari proses perencanaan pembangunan lokal, siapkan peta investasi modal dengan memastikan bahwa investasi tersebut disesuaikan dengan atau tidak berlokasi di dalam area yang rawan perubahan iklim."],
["challenge_name"=>"Perencanaan Penanaman Modal","name"=>"Gunakan inventarisasi gas rumah kaca untuk perencanaan investasi modal dengan mengintegrasikan data dari inventarisasi tersebut dengan kumpulan data dan prosedur yang digunakan untuk menyiapkan rencana investasi modal."],
["challenge_name"=>"Perencanaan Penanaman Modal","name"=>"Susun inventaris gas rumah kaca dengan data yang cukup rinci agar bermanfaat dalam perencanaan pembangunan dan pengambilan keputusan investasi modal."],
["challenge_name"=>"Perencanaan Penanaman Modal","name"=>"Integrasikan inventaris gas rumah kaca ke dalam perencanaan investasi modal dengan memperhitungkan emisi dan konsumsi energi saat ini dari infrastruktur yang ada, dengan ukuran spesifik lokasi tetapi juga ukuran universal (ekuivalen CO2)."],
["challenge_name"=>"Perencanaan Penanaman Modal","name"=>"Integrasikan inventarisasi gas rumah kaca ke dalam perencanaan investasi modal dengan memprediksi peningkatan atau penurunan emisi dan konsumsi energi yang diantisipasi dalam rencana."],
["challenge_name"=>"Perencanaan Penanaman Modal","name"=>"Integrasikan inventarisasi gas rumah kaca ke dalam perencanaan investasi modal dengan mengadopsi metodologi cerdas iklim untuk perencanaan investasi modal yang memastikan bahwa proyek infrastruktur dan desain PPP menunjukkan pilihan rendah karbon dan tahan terhadap perubahan iklim."],
["challenge_name"=>"Perencanaan Penanaman Modal","name"=>"Meninjau dan menyesuaikan prosedur yang ada untuk memaksimalkan efisiensi dalam pemilihan dan penentuan prioritas proyek rencana investasi modal dalam anggaran modal tahunan."],
["challenge_name"=>"Perencanaan Penanaman Modal","name"=>"Gunakan proses perencanaan investasi modal untuk memastikan bahwa proyek-proyek dalam setiap anggaran modal tahunan dipilih karena menawarkan jalur pembangunan yang rendah karbon, adaptif, dan tangguh."],
["challenge_name"=>"Perencanaan Penanaman Modal","name"=>"Merancang prosedur perencanaan investasi modal untuk mendapatkan nilai penuh dan mewujudkan biaya penuh dari investasi modal, dan oleh karena itu merencanakan investasi dengan cara yang bijaksana secara fiskal dan layak kredit."],
["challenge_name"=>"Perencanaan Penanaman Modal","name"=>"Buatlah daftar sumber pendanaan untuk proyek-proyek berdasarkan urutan prioritas untuk persetujuan formal rencana investasi modal."],
["challenge_name"=>"Perencanaan Penanaman Modal","name"=>"Melakukan penilaian terhadap proses dan prosedur termasuk penggunaan Teknologi Informasi untuk penyusunan rencana dan anggaran investasi modal, termasuk penggunaan perencanaan dan penganggaran yang ramah iklim."],
["challenge_name"=>"Perencanaan Penanaman Modal","name"=>"Berdasarkan tinjauan tersebut, siapkan rencana, jadwal, dan anggaran untuk mengintegrasikan Teknologi Informasi ke dalam proses penyusunan rencana dan anggaran investasi modal yang ramah iklim."],
["challenge_name"=>"Perencanaan Penanaman Modal","name"=>"Susun daftar konsultan Perencanaan Kota, Teknik, dan/atau Analis Keuangan (atau sumber daya alternatif) yang memiliki keahlian yang dibutuhkan."],
["challenge_name"=>"Perencanaan Keuangan Buruk","name"=>"Menyusun jadwal pelaksanaan proyek/PPP selama lima tahun dan perkiraan biaya awal untuk investasi modal yang ramah iklim sebagaimana yang diamanatkan dalam rencana pembangunan lokal."],
["challenge_name"=>"Perencanaan Keuangan Buruk","name"=>"Untuk semua proyek dalam rencana investasi modal, identifikasi mekanisme pembiayaan utang yang potensial berdasarkan urutan prioritas."],
["challenge_name"=>"Perencanaan Keuangan Buruk","name"=>"Untuk semua proyek dalam rencana investasi modal, identifikasi opsi pembiayaan PPP berdasarkan urutan prioritas."],
["challenge_name"=>"Perencanaan Keuangan Buruk","name"=>"Untuk semua proyek dalam rencana investasi modal, berdasarkan urutan prioritas, identifikasi potensi penggunaan mekanisme penangkapan nilai lahan untuk pembiayaan."],
["challenge_name"=>"Perencanaan Keuangan Buruk","name"=>"Gunakan penganggaran bergulir 5 tahun untuk pengeluaran modal yang termasuk dalam rencana investasi modal, dan identifikasi jumlah serta sumber pembiayaan untuk proyek-proyek dalam anggaran."],
["challenge_name"=>"Perencanaan Keuangan Buruk","name"=>"Perkirakan dampak pengeluaran terhadap anggaran operasional masa depan dari setiap proyek investasi dan PPP yang termasuk dalam rencana investasi modal (perhitungan biaya siklus hidup)."],
["challenge_name"=>"Perencanaan Keuangan Buruk","name"=>"Sertakan estimasi biaya operasional dan pemeliharaan saat mulai berlaku untuk proyek/PPP yang termasuk dalam anggaran modal ketika menyiapkan anggaran operasional tahunan dan memproyeksikan biaya operasional dua tahun ke depan."],
["challenge_name"=>"Perencanaan Keuangan Buruk","name"=>"Lakukan studi untuk memperkirakan basis dari mana setiap jenis pendapatan dari sumber sendiri diperoleh, bersama dengan perkiraan konservatif potensi pendapatan tambahan selama 3-5 tahun ke depan."],
["challenge_name"=>"Perencanaan Keuangan Buruk","name"=>"Buat dan kelola rekening cadangan untuk menerima surplus operasional di akhir setiap tahun fiskal."],
["challenge_name"=>"Perencanaan Keuangan Buruk","name"=>"Berdasarkan tinjauan terhadap proses penganggaran dan akuntansi, siapkan rencana, jadwal, dan anggaran untuk mengintegrasikan teknologi informasi ke dalam proses perencanaan dan manajemen keuangan."],
["challenge_name"=>"Kelaikan Kredit Tidak Diketahui","name"=>"Bicaralah dengan Pemerintah Daerah yang diberi peringkat untuk belajar dari pengalaman mereka dengan proses pemberian peringkat."],
["challenge_name"=>"Kelaikan Kredit Tidak Diketahui","name"=>"Tindak lanjut/penyempurnaan Penilaian Diri dan Rencana Aksi yang telah diselesaikan di Akademi Kelayakan Kredit."],
["challenge_name"=>"Kelaikan Kredit Tidak Diketahui","name"=>"Melibatkan, meningkatkan kesadaran, dan mencapai konsensus di antara pemangku kepentingan utama pemerintah pusat dan sektor keuangan swasta mengenai nilai dari adanya evaluasi independen terhadap kelayakan kredit Pemerintah Daerah."],
["challenge_name"=>"Kelaikan Kredit Tidak Diketahui","name"=>"Siapkan laporan keuangan yang diaudit selama 3 tahun dan perkiraan anggaran selama 5 tahun untuk digunakan dalam evaluasi kelayakan kredit."],
["challenge_name"=>"Kelaikan Kredit Tidak Diketahui","name"=>"Tinjau, bersama dengan penasihat keuangan publik independen, kondisi keuangan pemerintah daerah dan riwayat surplus margin operasional untuk menetapkan kapasitas pembayaran utang dan rencana pembiayaannya."],
["challenge_name"=>"Kelaikan Kredit Tidak Diketahui","name"=>"Susun daftar konsultan Keuangan Publik Independen yang memiliki keahlian yang dibutuhkan untuk membantu Pemerintah Daerah dalam berinteraksi dengan pasar modal dan dengan lembaga pemeringkat atau entitas lain yang dapat menilai dan mendokumentasikan kelayakan kredit."],
["challenge_name"=>"Kelaikan Kredit Tidak Diketahui","name"=>"Lakukan Penilaian Manajemen Keuangan komprehensif yang menyoroti area-area di mana perbaikan dapat dilakukan."],
["challenge_name"=>"Kelaikan Kredit Tidak Diketahui","name"=>"Selesaikan Penilaian PEFA (Pengeluaran Publik & Akuntabilitas Keuangan), atau PEFA ditambah dengan Penilaian Kinerja Manajemen Utang (DeMPA)."],
["challenge_name"=>"Kelaikan Kredit Tidak Diketahui","name"=>"Mulailah proses pemeringkatan formal dengan lembaga pemeringkat kredit yang diakui."],
["challenge_name"=>"Kelaikan Kredit Tidak Diketahui","name"=>"Dapatkan Peringkat Kredit Bayangan skala nasional dari lembaga pemeringkat kredit yang bereputasi."],
["challenge_name"=>"Kelaikan Kredit Tidak Diketahui","name"=>"Dapatkan peringkat kredit publik skala nasional (baik institusional maupun berbasis transaksi) dari lembaga pemeringkat kredit yang bereputasi."],
["challenge_name"=>"Sumber Modal Terbatas","name"=>"Lakukan penilaian terperinci terhadap sumber-sumber modal swasta jangka panjang yang secara hukum diizinkan untuk diakses oleh Pemerintah Daerah untuk pengembangan infrastruktur yang ramah iklim."],
["challenge_name"=>"Sumber Modal Terbatas","name"=>"Lakukan studi tinjauan umum mengenai pro dan kontra dari mekanisme pembiayaan potensial untuk memperluas akses pemerintah daerah terhadap pembiayaan swasta jangka panjang untuk proyek infrastruktur mereka."],
["challenge_name"=>"Sumber Modal Terbatas","name"=>"Lakukan tinjauan terhadap pro dan kontra dari mekanisme pembiayaan utang potensial (pinjaman, obligasi & pembiayaan gabungan) untuk memperluas akses pemerintah daerah terhadap pembiayaan swasta jangka panjang untuk proyek infrastruktur mereka."],
["challenge_name"=>"Sumber Modal Terbatas","name"=>"Lakukan tinjauan terhadap pro dan kontra dari mekanisme pembiayaan PPP potensial untuk memperluas akses pemerintah daerah terhadap pembiayaan swasta jangka panjang untuk proyek infrastruktur mereka."],
["challenge_name"=>"Sumber Modal Terbatas","name"=>"Lakukan tinjauan terhadap pro dan kontra dari mekanisme penangkapan nilai lahan potensial untuk memperluas akses pemerintah daerah terhadap pembiayaan swasta jangka panjang untuk proyek infrastruktur mereka."],
["challenge_name"=>"Sumber Modal Terbatas","name"=>"Meningkatkan kesadaran dan mencapai konsensus antara pemerintah nasional, pemerintah daerah, investor, dan pihak-pihak sektor swasta lainnya mengenai inisiatif untuk mendorong partisipasi swasta yang lebih besar dalam pembiayaan infrastruktur lokal."],
["challenge_name"=>"Sumber Modal Terbatas","name"=>"Melakukan riset dan memahami sudut pandang investor swasta terhadap pembiayaan infrastruktur jangka panjang serta reformasi spesifik yang diperlukan untuk memungkinkan partisipasi swasta yang lebih besar dalam pembiayaan infrastruktur lokal."],
["challenge_name"=>"Sumber Modal Terbatas","name"=>"Identifikasi serangkaian tugas yang harus dilakukan oleh pemerintah pusat dengan tujuan untuk meningkatkan pasar utang jangka panjang bagi Pemerintah Daerah."],
["challenge_name"=>"Sumber Modal Terbatas","name"=>"Menyelesaikan proyek percontohan penerbitan obligasi pemerintah daerah atau pinjaman jangka panjang untuk menguji kesiapan rezim peraturan saat ini dan pasar modal lokal dalam menyediakan pembiayaan utang jangka panjang swasta untuk infrastruktur ramah iklim."],
["challenge_name"=>"Sumber Modal Terbatas","name"=>"Selesaikan proyek percontohan kemitraan publik-swasta (PPP) pemerintah daerah untuk menguji kesiapan rezim peraturan saat ini dan bisnis swasta dalam menyediakan pembiayaan jangka panjang swasta untuk infrastruktur ramah iklim."],
["challenge_name"=>"Sumber Modal Terbatas","name"=>"Menyelesaikan proyek percontohan pembiayaan infrastruktur pemerintah daerah berdasarkan penangkapan nilai lahan untuk menguji kesiapan rezim peraturan saat ini serta pasar modal lokal dan pengembang properti dalam menyediakan pembiayaan jangka panjang swasta untuk infrastruktur ramah iklim."],
["challenge_name"=>"Masalah Lingkungan yang Mendukung","name"=>"Libatkan pemerintah nasional untuk membujuk mereka agar mengembangkan kebijakan, hukum, dan peraturan yang memungkinkan Pemerintah Daerah untuk menggunakan utang jangka panjang dan kemitraan publik-swasta (PPP) untuk membiayai investasi infrastruktur yang ramah iklim."],
["challenge_name"=>"Masalah Lingkungan yang Mendukung","name"=>"Mendorong pembentukan kerangka hukum dan peraturan untuk memungkinkan pembiayaan gabungan yang mencakup berbagai yurisdiksi."],
["challenge_name"=>"Masalah Lingkungan yang Mendukung","name"=>"Mendorong pembentukan kerangka hukum dan peraturan untuk memungkinkan pembiayaan bersama dan tanggung jawab bersama oleh berbagai yurisdiksi (misalnya, untuk tempat pembuangan sampah bersama)."],
["challenge_name"=>"Masalah Lingkungan yang Mendukung","name"=>"Meneliti dan memahami sudut pandang investor swasta terhadap pembiayaan infrastruktur jangka panjang dan reformasi spesifik yang diperlukan untuk memungkinkan partisipasi swasta yang lebih besar dalam pembiayaan infrastruktur lokal."],
["challenge_name"=>"Masalah Lingkungan yang Mendukung","name"=>"Tinjau dan revisi kerangka peraturan sehingga Pemerintah Daerah harus memperoleh Peringkat Kredit Skala Nasional sebelum mereka diberikan akses ke pembiayaan jangka panjang dari sumber mana pun."],
["challenge_name"=>"Masalah Lingkungan yang Mendukung","name"=>"Tinjau dan revisi kerangka peraturan agar investor institusional (misalnya, dana pensiun, perusahaan asuransi, dll.) dapat berinvestasi dalam obligasi Pemerintah Daerah yang memiliki peringkat kredit yang sesuai."],
["challenge_name"=>"Masalah Lingkungan yang Mendukung","name"=>"Tinjau dan revisi kerangka peraturan agar Pemerintah Daerah dapat memperoleh pembiayaan jangka panjang hanya dalam mata uang yang sama dengan mata uang yang mereka gunakan untuk mengumpulkan pendapatan."],
["challenge_name"=>"Masalah Lingkungan yang Mendukung","name"=>"Tinjau dan revisi kerangka peraturan agar Pemerintah Daerah dapat mengalokasikan aliran pendapatan internal tertentu dan menjaminkannya untuk pembayaran utang atau kewajiban Kemitraan Publik-Swasta (PPP)."],
["challenge_name"=>"Masalah Lingkungan yang Mendukung","name"=>"Menciptakan landasan hukum untuk penyitaan pendapatan multi-tahun dalam kondisi tertentu (misalnya, Pemerintah Daerah dapat menginstruksikan pemerintah pusat untuk mengarahkan sejumlah tetap transfer antar pemerintah mereka ke wali amanat untuk pembayaran layanan utang)."],
["challenge_name"=>"Masalah Lingkungan yang Mendukung","name"=>"Meninjau dan merevisi kerangka kebijakan dan hukum sehingga pemerintah tingkat atas tidak bertanggung jawab atas pembayaran jika pemerintah daerah gagal membayar utang atau kewajiban keuangan lainnya kepada investor, dan terdapat prosedur dan mekanisme hukum yang kredibel untuk menyelesaikan kegagalan pembayaran tersebut."],
["challenge_name"=>"Masalah Lingkungan yang Mendukung","name"=>"Mendorong pengembangan penyedia layanan khusus yang dibutuhkan untuk memungkinkan penggunaan pembiayaan pasar modal melalui obligasi pemerintah daerah, pembiayaan gabungan, dan kemitraan publik-swasta (PPP)."],
["challenge_name"=>"Masalah Lingkungan yang Mendukung","name"=>"Susun daftar konsultan penasihat keuangan publik independen dan penasihat hukum (atau sumber daya alternatif) yang memiliki keahlian yang dibutuhkan untuk membantu mengembangkan dan menegosiasikan reformasi lingkungan yang mendukung pembiayaan jangka panjang."],
["challenge_name"=>"Kurangnya Pengalaman Pembiayaan","name"=>"Carilah penasihat keuangan publik independen yang berpengalaman untuk membantu menyelesaikan program percontohan pinjaman jangka panjang, atau penerbitan obligasi."],
